// Application-owned local handler for Prompt 72.
// s is the lesson state; p contains validated classroom controls.
switch (action.op) {
    case 'network.check': {
        const host = p.host || (p.context === 'mcp' ? 'mcp.example.test' : 'registry.npmjs.org');
        const allowed = p.context === 'package' ? !!p.allowPackages : p.context === 'mcp' ? !!p.allowMcp : host === 'api.example.test' || host.endsWith('.docs.example.test');
        const evidence = { host, allowed, rule: p.context || 'api.example.test and *.docs.example.test', requestSent: false };
        if (allowed)
            accept(evidence);
        else
            reject('Destination is outside the configured allowlist.', evidence);
        break;
    }
}
